using System;
using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "LunarAlignmentAction", menuName = "Data/Battle/Battle Actions/Moonie/LunarAlignment Action")]
public class LunarAlignmentAction : ReductionAction
{
	public override void CastAmount(int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		bool flag = false;
		int purifyAmount = GetPurifyAmount(amount);
		List<DiceInstance> diceInstancesToDecrease = GetDiceInstancesToDecrease();
		for (int i = 0; i < diceInstancesToDecrease.Count; i++)
		{
			DiceInstance diceInstance = diceInstancesToDecrease[i];
			bool flag2 = false;
			bool spawnBurst = false;
			Action afterDiceToPlayerActionAfterDelay = null;
			if (diceInstance.ActionFace.BattleAction is PurifyAction)
			{
				diceInstance.ActionFace.ActionValue = finalValue;
				flag2 = true;
				if (!flag)
				{
					flag = true;
					spawnBurst = true;
					afterDiceToPlayerActionAfterDelay = delegate
					{
						InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.5f, delegate
						{
							targetToPurifyLogic.ActivateOmen(purifyAction, purifyAmount, null, source);
						});
					};
				}
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is PurifyAction)
			{
				diceInstance.ActionFace.SecondActionValue = finalValue;
				flag2 = true;
				if (!flag)
				{
					flag = true;
					spawnBurst = true;
					afterDiceToPlayerActionAfterDelay = delegate
					{
						InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.5f, delegate
						{
							targetToPurifyLogic.ActivateOmen(purifyAction, purifyAmount, null, source);
						});
					};
				}
			}
			if (flag2)
			{
				diceInstance.ActionFace.RemoveActionValueModifier(battleActionInteractionEnum);
				diceInstance.UpdateDiceFace();
				if (IsVFXEnabled())
				{
					GetVFX().GetComponent<DiceToPlayerToBurstVFX>().Initialize(diceInstance.transform.position, spawnBurst, afterDiceToPlayerActionAfterDelay);
				}
			}
		}
		if (!IsVFXEnabled())
		{
			targetToPurifyLogic.ActivateOmen(purifyAction, purifyAmount, null, source);
		}
	}

	private List<DiceInstance> GetDiceInstancesToDecrease()
	{
		List<DiceInstance> list = new List<DiceInstance>();
		list.AddRange(ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices);
		list.AddRange(base.currentCorruptedAnimals.GetEnemiesDiceInstances());
		list.AddRange(base.currentCompanions.GetSentinelsDiceInstances());
		return list;
	}

	public int GetPurifyAmount(int amount)
	{
		if (ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance == null)
		{
			return 0;
		}
		int num = 0;
		List<DiceInstance> diceInstancesToDecrease = GetDiceInstancesToDecrease();
		for (int i = 0; i < diceInstancesToDecrease.Count; i++)
		{
			DiceInstance diceInstance = diceInstancesToDecrease[i];
			if (diceInstance.ActionFace.BattleAction is PurifyAction)
			{
				num++;
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is PurifyAction)
			{
				num++;
			}
		}
		return num * amount;
	}
}
